define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_53.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e200095","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_54.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e200199","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_51.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e200303","topics":[]},{"title":"Removing the High Order Shim (HOS) power supply","shortdesc":"<p class=\"shortdesc\">Removes either the NavShim or ProDrive High Order Shim (HOS) power supply from the Integrated System Cabinet (ISC).<\/p>","href":"t_RemovingTheHighOrderShimHOSPowerSupply.html","attributes":{"data-id":"id_2016549"},"menu":{"hasChildren":false},"tocID":"id_2016549-d46e200407","topics":[]},{"title":"Installing the High Order Shim (HOS) power supply","shortdesc":"<p class=\"shortdesc\">Installs either the NavShim or ProDrive High Order Shim (HOS) power supply into the Integrated System Cabinet (ISC).<\/p>","href":"t_InstallingTheHighOrderShimHOSPowerSupply.html","attributes":{"data-id":"id_2016550"},"menu":{"hasChildren":false},"tocID":"id_2016550-d46e200511","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_53.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e200615","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_53.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e200719","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_80.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e200823","topics":[]},{"title":"Doing the High Order Shim (HOS) supply diagnostics","shortdesc":"<p class=\"shortdesc\">These diagnostics allow setting of currents on various High Order Shim (HOS) channels, and reading of these currents. In addition, various tests allow you to determine the functionality of the HOS circuit and the health of the supply.<\/p>","href":"t_DoingTheHighOrderShimHOSFunctionalCheck_2.html","attributes":{"data-id":"id_2016834"},"menu":{"hasChildren":false},"tocID":"id_2016834-d46e200927","topics":[]}]});